#include "record.h"

static int read_record(struct Record *record)
{
    int part = getchar();
    if ((part != 'A' && part != 'B') || getchar() != ' ') {
        return 0;
    }
    int quantity = getchar();
    if (quantity < '0' || quantity > '9') {
        return 0;
    }
    int tail = getchar();
    if (tail != '\n' && tail != EOF) {
        return 0;
    }
    record->part = (char) part;
    record->quantity = quantity - '0';
    return 1;
}

int main(void)
{
    struct Record order;
    if (!read_record(&order)) {
        puts("invalid");
        return 1;
    }
    int total = record_total(order);
    if (total < 0) {
        puts("invalid");
        return 1;
    }
    printf("total=%d\n", total);
    return 0;
}

