#include "record.h"

static int unit_price(char part)
{
    return part == 'A' ? 3 : 5;
}

int record_total(struct Record record)
{
    if ((record.part != 'A' && record.part != 'B') ||
        record.quantity < 0 || record.quantity > 6) {
        return -1;
    }
    return record.quantity * unit_price(record.part);
}

